def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Degree of the candidate among uncoloured neighbours divided by how many free colours it still has (hub with few options is urgent)."""
    k, c = neighbor_colors.shape
    if k == 0:
        return np.zeros(0)
    uncol = adjacency.sum(axis=1).astype(float)
    uncol_norm = uncol / max(k - 1, 1)
    if c == 0:
        free_count = np.ones(k, dtype=float)
    else:
        free_count = (neighbor_colors == 0).sum(axis=1).astype(float)
    # few free colours + many uncoloured neighbours -> constrained hub, should go early
    squeeze = uncol_norm / (free_count + 1.0)
    return squeeze

