def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Uncoloured-degree share times the shortfall of free colours below the per-decision mean (normalised by c), clipped to [-1, 1]."""
    k = adjacency.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    uncol = adjacency.sum(axis=1).astype(float)
    deg = np.asarray(degree, dtype=float)
    res_share = np.where(deg > 0, uncol / np.maximum(deg, 1.0), 0.0)
    free_count = (neighbor_colors == 0).sum(axis=1).astype(float)
    d = (free_count.mean() - free_count) / float(c)
    return np.clip(res_share * d, -1.0, 1.0)

