def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Total size of the colour classes whose colour each candidate can still take, divided by the number of coloured vertices."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    free = (neighbor_colors == 0).astype(float)
    mass = free @ np.asarray(color_sizes, dtype=float)
    total = float(color_sizes.sum())
    return mass / max(total, 1.0)

