def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Residual-degree hub ratio: (R - mean residual degree of uncoloured neighbours) / (R + that mean)."""
    R = adjacency.sum(1).astype(float)
    M = (adjacency.astype(float) @ R) / np.maximum(R, 1)
    return (R - M) / np.maximum(R + M, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """1.0 for candidates whose assigned colour is the newest colour c-1, else 0.0 (zeros when c == 0)."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k, dtype=float)
    free = (neighbor_colors == 0)
    # first free colour index per row, else c
    has_free = free.any(axis=1)
    first_free = np.argmax(free, axis=1)  # 0 where no free colour, but masked below
    assigned = np.where(has_free, first_free, c)
    return (assigned == (c - 1)).astype(float)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Residual-degree share times colour-coverage density sat/(1+cd) of coloured neighbours."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    R = adjacency.sum(axis=1).astype(float)
    Rhat = R / max(k - 1, 1)
    if c == 0:
        return np.zeros(k)
    sat = (neighbor_colors > 0).sum(axis=1).astype(float)
    cd = neighbor_colors.sum(axis=1).astype(float)
    return Rhat * sat / (1.0 + cd)
